import { useState } from "react"
import { cn } from "../lib/utils"
import { Button } from "./ui/button"
import { ScrollArea } from "./ui/scroll-area"
import {
  Home,
  Layers,
  Users,
  BarChart3,
  FileText,
  Settings,
  ChevronRight,
  X,
} from "lucide-react"

export interface NavItem {
  id: string
  label: string
  icon: React.ReactNode
  children?: NavItem[]
}

const navItems: NavItem[] = [
  { id: "overview", label: "产品概述", icon: <Home className="h-4 w-4" /> },
  { id: "features", label: "功能详解", icon: <Layers className="h-4 w-4" /> },
  { id: "users", label: "目标用户", icon: <Users className="h-4 w-4" /> },
  { id: "architecture", label: "技术架构", icon: <BarChart3 className="h-4 w-4" /> },
  { id: "tech-stack", label: "技术方案", icon: <Settings className="h-4 w-4" /> },
  { id: "roadmap", label: "产品路线", icon: <FileText className="h-4 w-4" /> },
]

interface SidebarProps {
  activeSection: string
  onSectionChange: (section: string) => void
  isOpen: boolean
  onClose: () => void
}

export function Sidebar({ activeSection, onSectionChange, isOpen, onClose }: SidebarProps) {
  const [expandedItems, setExpandedItems] = useState<string[]>([])

  const toggleExpand = (id: string) => {
    setExpandedItems((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    )
  }

  return (
    <>
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 lg:hidden"
          onClick={onClose}
        />
      )}
      <aside
        className={cn(
          "fixed top-14 z-40 h-[calc(100vh-3.5rem)] w-72 border-r bg-background transition-transform duration-200 lg:translate-x-0",
          isOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <ScrollArea className="h-full py-4">
          <div className="px-4 lg:hidden">
            <Button
              variant="ghost"
              size="icon"
              className="absolute right-4 top-4"
              onClick={onClose}
            >
              <X className="h-5 w-5" />
            </Button>
          </div>
          <nav className="space-y-1 px-2">
            {navItems.map((item) => (
              <div key={item.id}>
                <Button
                  variant={activeSection === item.id ? "secondary" : "ghost"}
                  className={cn(
                    "w-full justify-start gap-2",
                    activeSection === item.id && "bg-secondary"
                  )}
                  onClick={() => {
                    onSectionChange(item.id)
                    onClose()
                  }}
                >
                  {item.icon}
                  <span className="flex-1 text-left">{item.label}</span>
                  {item.children && (
                    <ChevronRight
                      className={cn(
                        "h-4 w-4 transition-transform",
                        expandedItems.includes(item.id) && "rotate-90"
                      )}
                      onClick={(e) => {
                        e.stopPropagation()
                        toggleExpand(item.id)
                      }}
                    />
                  )}
                </Button>
                {item.children && expandedItems.includes(item.id) && (
                  <div className="ml-6 mt-1 space-y-1">
                    {item.children.map((child) => (
                      <Button
                        key={child.id}
                        variant={activeSection === child.id ? "secondary" : "ghost"}
                        className="w-full justify-start gap-2 pl-8"
                        onClick={() => {
                          onSectionChange(child.id)
                          onClose()
                        }}
                      >
                        {child.icon}
                        <span>{child.label}</span>
                      </Button>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </nav>
        </ScrollArea>
      </aside>
    </>
  )
}

export { navItems }

